begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('29000000-0000-4000-8000-000000000001','speech-quota@example.test');
insert into learning_workspaces(id,user_id,title) values('29000000-0000-4000-8000-000000000002','29000000-0000-4000-8000-000000000001','Quota');
insert into learning_private.job_requests(user_id,kind,created_at) select '29000000-0000-4000-8000-000000000001',case when n%2=0 then 'SPEECH_PROMPT' else 'SPEECH_RECORDING' end,clock_timestamp()-interval '2 minutes' from generate_series(1,30) n;
set local role authenticated;
select set_config('request.jwt.claim.sub','29000000-0000-4000-8000-000000000001',true);
select throws_ok($$select begin_speech_upload(gen_random_uuid(),'29000000-0000-4000-8000-000000000002',null,'','audio/wav',100,repeat('a',64))$$,'P0001','LEARNING_LIMIT','Mixed speech kinds share thirty requests per day');
reset role;
delete from learning_private.job_requests where user_id='29000000-0000-4000-8000-000000000001';
insert into learning_private.job_requests(user_id,kind) select '29000000-0000-4000-8000-000000000001','SPEECH_RECORDING' from generate_series(1,10);
set local role authenticated;
select throws_ok($$select learning_speech_command(jsonb_build_object('action','PROMPT','requestId',gen_random_uuid(),'id',gen_random_uuid(),'workspaceId','29000000-0000-4000-8000-000000000002','level','EASY','topic',''))$$,'P0001','LEARNING_LIMIT','Speech burst cannot exceed ten requests per minute');
reset role;
delete from learning_private.job_requests where user_id='29000000-0000-4000-8000-000000000001';
insert into learning_ai_jobs(user_id,workspace_id,kind,status,input) select '29000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000002','STUDY_SUMMARY','QUEUED','{}' from generate_series(1,3);
set local role authenticated;
select throws_ok($$select begin_speech_upload(gen_random_uuid(),'29000000-0000-4000-8000-000000000002',null,'','audio/wav',100,repeat('a',64))$$,'P0001','LEARNING_LIMIT','Text jobs consume shared speech capacity');
reset role;
delete from learning_ai_jobs where user_id='29000000-0000-4000-8000-000000000001';
insert into learning_speech(id,user_id,workspace_id,kind,status) select gen_random_uuid(),'29000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000002','RECORDING','UPLOADING' from generate_series(1,3);
create temporary table quota_session(v jsonb);
grant all on quota_session to authenticated;
set local role authenticated;
insert into quota_session select learning_command(jsonb_build_object('action','START','requestId',gen_random_uuid(),'workspaceId','29000000-0000-4000-8000-000000000002','deviceId','29000000-0000-4000-8000-000000000003','timezone','Asia/Seoul'))->'session';
select throws_ok($$select learning_command((select jsonb_build_object('action','MESSAGE','requestId',gen_random_uuid(),'workspaceId',v->>'workspace_id','sessionId',v->>'id','deviceId',v->>'device_id','generation',(v->>'generation')::integer,'content','Hello') from quota_session))$$,'P0001','LEARNING_LIMIT','Speech uploads consume shared text capacity');
select is((select count(*) from learning_messages where user_id=auth.uid()),0::bigint,'Rejected text admission rolls back its message');
reset role;
select * from finish();
rollback;
